import{_ as d,o as e,c as s,ag as a}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"MovCW 圆弧摆动","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovCW.md","filePath":"3. 指令/1. 运动指令/MovCW.md","lastUpdated":1778862643000}'),i={name:"3. 指令/1. 运动指令/MovCW.md"};function o(r,t,n,h,l,p){return e(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="movcw-圆弧摆动" tabindex="-1">MovCW 圆弧摆动 <a class="header-anchor" href="#movcw-圆弧摆动" aria-label="Permalink to &quot;MovCW 圆弧摆动&quot;">​</a></h1><p>圆弧摆动指令（MovCW）是指机器人根据设定的摆动频率、摆动幅度，在圆弧前进的过程中同时进行摆弧运动。该指令结合了圆弧插补（MovC）与摆动功能（Weave），常用于圆弧形焊缝的编织焊接。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovCW(A, P, [V], [B], [C], [Tool], [Coord], [PayLoad], WEAVE, [O], [DO])</p><p>MovCW(中间点, 目标点, [速度], [平滑], [姿态], [工具], [坐标系], [负载], 摆动参数, [姿态控制], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>A</td><td>APOS 或 CPOS 变量</td><td>辅助点位置，用于确定圆弧的曲率半径和运动方向。该点的姿态不会影响最终的轨迹运行。</td><td>必填</td></tr><tr><td>P</td><td>APOS 或 CPOS 变量</td><td>坐标系下的目标终点位置。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>指定机器人执行圆弧运动的速度。SPEED 变量中的 <code>tcp</code>（平移速度）和 <code>ori</code>（旋转速度）分量有效；如有外部轴，则 <code>exj_l</code>、<code>exj_r</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点时的过渡方式（无过渡、相对、绝对、缺省）。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡半径或数值。</td><td>可选，默认 C100</td></tr><tr><td>[Tool]</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数。</td><td>可选，默认使用当前系统中设置的工具参数</td></tr><tr><td>[Coord]</td><td>USERCOOR 变量 / 变位机变量</td><td>执行轨迹时使用的用户坐标系或变位机坐标系。</td><td>可选，默认使用当前系统中设置的坐标系参数</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的工件负载参数。</td><td>可选，默认使用当前系统中设置的负载参数</td></tr><tr><td>WEAVE</td><td>WEAVE 变量</td><td>存储摆动动作的核心控制参数，包括：<strong>摆频</strong>（每秒摆动的次数）、<strong>摆幅</strong>（摆动的覆盖宽度）、<strong>停止时间</strong>（在摆动两侧端点的停留时间）、<strong>旋转</strong>（摆动过程中的姿态补偿）。</td><td>必填</td></tr><tr><td>[O]</td><td>enum（GOVRON / GOVROFF）</td><td><code>GOVRON</code>：本段轨迹受全局速度倍率影响（默认）。<br><code>GOVROFF</code>：本段轨迹不受全局速度倍率影响。</td><td>可选，默认 GOVRON</td></tr><tr><td>[DO]</td><td>string</td><td>指令执行完后可触发的额外 IO 操作。目前支持：<code>SetDO</code>、<code>SetAO</code>、<code>SetSimDO</code>、<code>SetSimAO</code>、<code>PulseOut</code>、<code>PulseSimOut</code>、<code>SetDO8421</code>、<code>SetSimDO8421</code>、<code>SetDIEdge</code>、<code>SetSimDIEdge</code>。</td><td>可选</td></tr></tbody></table><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovCW</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, P2, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, WV1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, DO1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>机器人将结合 <strong>WV1</strong> 摆动参数，经过 <strong>P1</strong> 运动至 <strong>P2</strong>，完成一个带摆动动作的圆周运动轨迹。</p>',13)])])}const E=d(i,[["render",o]]);export{k as __pageData,E as default};
